package com.cursorclarity;

import javax.inject.Singleton;

@Singleton
class CursorClickState
{
	private volatile long lastClickTime = -1;

	void recordClick()
	{
		lastClickTime = System.currentTimeMillis();
	}

	long getLastClickTime()
	{
		return lastClickTime;
	}
}

package com.cursorclarity;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class CursorClarityOverlay extends Overlay
{
	// How long the ring stays fully visible after the mouse stops moving, before it starts fading (ms)
	private static final long IDLE_GRACE_MS = 400;
	// How long the fade-out takes once it starts (ms)
	private static final long IDLE_FADE_MS = 600;

	private final Client client;
	private final CursorClarityConfig config;
	private final CursorClickState clickState;

	private Point lastMousePos = null;
	private long lastMoveTime = System.currentTimeMillis();

	@Inject
	private CursorClarityOverlay(Client client, CursorClarityConfig config, CursorClickState clickState)
	{
		this.client = client;
		this.config = config;
		this.clickState = clickState;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ALWAYS_ON_TOP);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (config.onlyInCombat())
		{
			if (client.getLocalPlayer() == null || client.getLocalPlayer().getInteracting() == null)
			{
				return null;
			}
		}

		net.runelite.api.Point mouse = client.getMouseCanvasPosition();
		if (mouse == null || mouse.getX() < 0 || mouse.getY() < 0)
		{
			return null;
		}

		Point currentPos = new Point(mouse.getX(), mouse.getY());
		long now = System.currentTimeMillis();

		if (lastMousePos == null || !currentPos.equals(lastMousePos))
		{
			lastMousePos = currentPos;
			lastMoveTime = now;
		}

		float alpha = config.opacity() / 100f;
		if (config.hideWhenIdle())
		{
			long idleFor = now - lastMoveTime;
			if (idleFor > IDLE_GRACE_MS)
			{
				long fadeProgress = idleFor - IDLE_GRACE_MS;
				float idleFade = 1f - Math.min(1f, fadeProgress / (float) IDLE_FADE_MS);
				alpha *= idleFade;
				if (alpha <= 0f)
				{
					return null;
				}
			}
		}

		int baseRadius = config.radius();
		int radius = baseRadius;
		if (config.pulse())
		{
			// Smooth sine pulse, +/- 15% of base radius, ~1.5s period
			double phase = (now % 1500) / 1500.0 * 2 * Math.PI;
			radius = (int) (baseRadius + Math.sin(phase) * baseRadius * 0.15);
		}

		if (config.clickAnimation() && clickState.getLastClickTime() > 0)
		{
			long sinceClick = now - clickState.getLastClickTime();
			int duration = config.clickAnimationDuration();
			if (sinceClick >= 0 && sinceClick < duration)
			{
				float t = sinceClick / (float) duration;
				radius = (int) (radius * easeOutBack(t));
			}
		}

		if (radius < 1)
		{
			radius = 1;
		}

		Color base = config.ringColor();
		Color drawColor = new Color(
			base.getRed(),
			base.getGreen(),
			base.getBlue(),
			Math.round(base.getAlpha() * alpha)
		);

		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setColor(drawColor);
		graphics.setStroke(new java.awt.BasicStroke(config.thickness()));

		Ellipse2D.Double ring = new Ellipse2D.Double(
			currentPos.x - radius,
			currentPos.y - radius,
			radius * 2.0,
			radius * 2.0
		);
		graphics.draw(ring);

		return null;
	}

	/**
	 * Starts at 0 (ring collapsed to the cursor point) and eases up past 1 with a
	 * slight overshoot before settling exactly at 1 (normal radius) — gives the ring
	 * a springy "pop back out" feel instead of a flat linear grow.
	 */
	private static float easeOutBack(float t)
	{
		float c1 = 1.70158f;
		float c3 = c1 + 1f;
		float x = t - 1f;
		return 1f + c3 * x * x * x + c1 * x * x;
	}
}

package com.cursorclarity;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("cursorclarity")
public interface CursorClarityConfig extends Config
{
	@ConfigItem(
		keyName = "ringColor",
		name = "Ring color",
		description = "Color of the circle drawn around your cursor",
		position = 1
	)
	default Color ringColor()
	{
		return Color.RED;
	}

	@ConfigItem(
		keyName = "radius",
		name = "Radius",
		description = "Radius of the cursor ring in pixels",
		position = 2
	)
	@Range(min = 4, max = 60)
	default int radius()
	{
		return 16;
	}

	@ConfigItem(
		keyName = "thickness",
		name = "Ring thickness",
		description = "Stroke width of the cursor ring",
		position = 3
	)
	@Range(min = 1, max = 12)
	default int thickness()
	{
		return 3;
	}

	@ConfigItem(
		keyName = "opacity",
		name = "Opacity (%)",
		description = "Transparency of the ring, from 1% (nearly invisible) to 100% (fully solid)",
		position = 4
	)
	@Range(min = 1, max = 100)
	default int opacity()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "pulse",
		name = "Pulse animation",
		description = "Slowly grow/shrink the ring so it's easier to spot out of the corner of your eye",
		position = 5
	)
	default boolean pulse()
	{
		return true;
	}

	@ConfigItem(
		keyName = "onlyInCombat",
		name = "Only show in combat",
		description = "Only draw the ring while your character is in combat (has a combat interaction)",
		position = 6
	)
	default boolean onlyInCombat()
	{
		return false;
	}

	@ConfigItem(
		keyName = "hideWhenIdle",
		name = "Hide when mouse is idle",
		description = "Fade the ring out after the mouse stops moving for a bit",
		position = 7
	)
	default boolean hideWhenIdle()
	{
		return false;
	}

	@ConfigItem(
		keyName = "clickAnimation",
		name = "Click animation",
		description = "Ring briefly collapses toward the cursor then springs back out when you click",
		position = 8
	)
	default boolean clickAnimation()
	{
		return true;
	}

	@ConfigItem(
		keyName = "clickAnimationDuration",
		name = "Click animation duration (ms)",
		description = "How long the collapse-and-spring-back animation takes",
		position = 9
	)
	@Range(min = 100, max = 800)
	default int clickAnimationDuration()
	{
		return 250;
	}
}

package com.cursorclarity;

import java.awt.event.MouseEvent;
import javax.inject.Inject;
import net.runelite.client.input.MouseAdapter;

class CursorClarityMouseListener extends MouseAdapter
{
	private final CursorClickState clickState;

	@Inject
	private CursorClarityMouseListener(CursorClickState clickState)
	{
		this.clickState = clickState;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent event)
	{
		clickState.recordClick();
		return event;
	}
}

package com.cursorclarity;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Cursor Clarity",
	description = "Draws a highlighted ring around your mouse cursor so it's easier to track during fast-paced combat, similar to cursor-highlight addons in other games.",
	tags = {"cursor", "mouse", "highlight", "accessibility", "combat", "overlay"}
)
public class CursorClarityPlugin extends Plugin
{
	@Inject
	private OverlayManager overlayManager;

	@Inject
	private CursorClarityOverlay overlay;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private CursorClarityMouseListener mouseListener;

	@Provides
	CursorClarityConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CursorClarityConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		mouseManager.registerMouseListener(mouseListener);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		mouseManager.unregisterMouseListener(mouseListener);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!event.getGroup().equals("cursorclarity"))
		{
			return;
		}
		// Overlay reads live from config each render, nothing to cache here.
	}
}
